from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    if not isinstance(paren_string, str) or not paren_string.strip():
        return []

    def get_max_depth(group: str) -> int:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

            if current_depth < 0:
                raise ValueError("Malformed group: closing parenthesis before opening.")

        if current_depth != 0:
            raise ValueError("Malformed group: unbalanced parentheses.")

        return max_depth

    return [get_max_depth(group) for group in paren_string.split()]
